function assertNever(x: never): never {
  throw new Error("Kasus tidak ditangani: " + JSON.stringify(x));
}
type Status = "menunggu" | "dibayar" | "dikirim";

function ikon(s: Status): string {
  switch (s) {
    case "menunggu":
      return "[ ]";
    case "dibayar":
      return "[$]";
    case "dikirim":
      return "[>]";
    default:
      return assertNever(s);
  }
}
const semua: Status[] = ["dikirim", "menunggu"];
console.log(semua.map(ikon).join(" "));

