cards.solution:
function assertNever(x: never): never {
  throw new Error("Kasus tidak ditangani: " + JSON.stringify(x));
}
type Ukuran = "S" | "M" | "L" | "XL";
function harga(u: Ukuran): number {
  switch (u) {
    case "S":
      return 15000;
    case "M":
      return 18000;
    case "L":
      return 21000;
    case "XL":
      return 25000;
    default:
      return assertNever(u);
  }
}
const pesanan: Ukuran[] = ["M", "XL", "S"];
console.log(pesanan.reduce((a, u) => a + harga(u), 0));
